-- Hand-curated English Retail routes. Story achievements use chapters,
-- not the obsolete quest-count totals in the original Wrath comments.
local _, TDP = ...
local guides=TDP.CollectionWalkthroughs.achievements
local function pin(mapID,x,y,step,label,mapName)
    return {mapID=mapID,x=x/100,y=y/100,step=step,label=label,mapName=mapName}
end
local function add(id,name,steps,waypoints,tips,comments,category)
    local lines,sources={},{}
    for i,text in ipairs(steps) do lines[i]=i..". "..text end
    for _,c in ipairs(comments or {}) do sources[#sources+1]=type(c)=="number" and ("https://www.wowhead.com/achievement="..id.."#comments:id="..c) or c end
    guides[id]={achievementId=id,name=name,category=category or "Quests",sourceType="Achievement",source=name,
        acquisition=table.concat(lines,"\n\n"),stepCount=#steps,waypoints=waypoints or {},tips=tips,sources=sources,
        wowheadUrl="https://www.wowhead.com/achievement="..id,sourceURL="https://www.wowhead.com/achievement="..id.."#comments"}
end
local storyTip="Enable Trivial Quests in tracking and follow the full named chapter to its final turn-in. A missing quest marker can mean a prerequisite, a quest-starting item in your bags, or a summons item with its own quest giver. Old 100/130/150-quest counters no longer describe this Retail achievement."

